def parse_grids_from_msg(s, name='Demo pair'):
    pairs={}
    for n in range(1,5):
        mi=re.search(fr'Demo pair {n} input \(12x12\):\n',s)
        mo=re.search(fr'Demo pair {n} output \(12x12\):\n',s)
        if mi and mo:
            def parse_rows(block):
                rows=[]
                for l in block.splitlines():
                    try: row=list(map(int,l.split()))
                    except: break
                    if len(row)!=12: break
                    rows.append(row)
                    if len(rows)==12:break
                return np.array(rows,dtype=int)
            a=parse_rows(s[mi.end():mo.start()])
            b=parse_rows(s[mo.end():])
            pairs[n]=(a,b)
    return pairs
